script:
// Gold Rush Tycoon v18 - bigger bases, reclaimable armory, world admin commands.
Game.on('join', function (name) { Game.toast(name + ' joined the Gold Rush!'); });

var WON = false;
Game.on('collect', function () {
  if (!WON && Game.money() >= 40000) { WON = true; Game.banner('GOLD TYCOON! You hit $40,000!'); }
});
Game.on('buy', function (label) {
  if (label === 'FREE Dropper') Game.toast('Ore rides the belt into your vault - step on the vault to sweep it.');
  if (label === 'Base Walls') Game.toast('Walls up - only you can pass your door.');
  if (label === '2nd Floor + Stairs') Game.toast('Stairs are by the left wall.');
  if (label === 'MEGA Dropper') Game.banner('A MEGA DROPPER roars to life!');
  if (label === 'DIAMOND Dropper') Game.banner('DIAMOND DROPS! The mine sparkles.');
});
Game.on('zwave', function (n) { Game.toast(n + ' zombies rise in the plaza!'); });

// admin-only announcements: receivers check the sender really is an admin
Game.onNet('announce', function (d, from) {
  if (!Game.isAdmin(from) || !d || typeof d.t !== 'string') return;
  Game.banner(d.t.slice(0, 120));
});

var SPOTS = { ne: [100, -60], nw: [-100, -60], se: [100, 60], sw: [-100, 60], mid: [0, 12] };

// ---------- WORLD ADMIN COMMANDS (chat, admins only) ----------
Game.on('cmd', function (text) {
  if (text.charAt(0) !== '/') return false;
  var p = text.slice(1).split(/\s+/);
  var c = (p[0] || '').toLowerCase();
  var known = ['help', 'money', 'setmoney', 'give', 'weapons', 'weapon', 'pet', 'zombies', 'unlock',
    'heal', 'tp', 'resetplot', 'reset', 'time', 'announce'];
  if (known.indexOf(c) < 0) return false;
  if (!Game.isAdmin()) { Game.toast('Admin only - enter the admin code in the menu first.', true); return true; }
  if (c === 'help') {
    Game.banner('/money N  /setmoney N  /give item  /weapons  /weapon item dmg  /pet r d z  /zombies N  /unlock  /heal  /tp ne|nw|se|sw|mid  /resetplot id  /reset  /time day|night|H  /announce text');
    return true;
  }
  if (c === 'money') { Game.addMoney(Math.round(+p[1] || 0)); Game.toast('Admin: money added'); return true; }
  if (c === 'setmoney') { Game.addMoney(Math.round(+p[1] || 0) - Game.money()); Game.toast('Admin: money set'); return true; }
  if (c === 'give') {
    if (!p[1]) { Game.toast('Usage: /give ' + Game.items().join(' | '), true); return true; }
    Game.give(p[1]); Game.toast('Admin: gave ' + p[1]); return true;
  }
  if (c === 'weapons') {
    var all = Game.items();
    for (var i = 0; i < all.length; i++) if (all[i] !== 'golden-apple') Game.give(all[i]);
    Game.toast('Admin: all weapons'); return true;
  }
  if (c === 'weapon') {
    var d = Math.round(+p[2] || 0);
    if (!p[1] || !d) { Game.toast('Usage: /weapon item damage', true); return true; }
    Game.tuneItem(p[1], { damage: d, pvp: Math.round(d * 1.5) });
    Game.toast('Admin: ' + p[1] + ' -> ' + d + ' dmg'); return true;
  }
  if (c === 'pet') {
    var r = +p[1] || 0, pd = +p[2] || 0, z = +p[3] || 0;
    if (!r || !pd || !z) { Game.toast('Usage: /pet radius damage zapRange', true); return true; }
    Game.tuneItem('storm-pet', { radius: r, damage: pd, zapRange: z });
    Game.toast('Admin: pet tuned'); return true;
  }
  if (c === 'zombies') { var me = Game.pos(); var n = Game.zombies(Math.min(8, +p[1] || 4), me.x, me.z, 30); Game.toast('Admin: ' + n + ' zombies'); return true; }
  if (c === 'unlock') {
    var mine = Game.myPlots();
    if (!mine.length) { Game.toast('Claim a plot first.', true); return true; }
    var bs = Game.buttons(mine[0]), k = 0;
    for (var j = 0; j < bs.length; j++) if (!bs[j].bought && !bs[j].give && Game.adminBuy(bs[j].id)) k++;
    Game.toast('Admin: unlocked ' + k + ' upgrades'); return true;
  }
  if (c === 'heal') { Game.heal(9999); Game.toast('Admin: healed'); return true; }
  if (c === 'tp') {
    var s = SPOTS[(p[1] || '').toLowerCase()];
    if (!s) { Game.toast('Usage: /tp ne|nw|se|sw|mid', true); return true; }
    Game.tp(s[0], 13, s[1]); return true;
  }
  if (c === 'resetplot') {
    var id = p[1] ? (p[1].indexOf('plot-') === 0 ? p[1] : 'plot-' + p[1]) : '';
    if (!id) { Game.toast('Usage: /resetplot ne|nw|se|sw', true); return true; }
    Game.resetPlot(id); Game.toast('Admin: reset ' + id); return true;
  }
  if (c === 'reset') { Game.resetWorld(); return true; }
  if (c === 'time') {
    var a = (p[1] || '').toLowerCase();
    var h = a === 'day' ? 12 : a === 'night' ? 0 : +a;
    if (!isFinite(h) || a === '') { Game.toast('Usage: /time day|night|0-24', true); return true; }
    Game.setTime(h); Game.toast('Admin: time ' + h); return true;
  }
  if (c === 'announce') {
    var t = text.slice(10).trim();
    if (!t) { Game.toast('Usage: /announce message', true); return true; }
    Game.banner(t); Game.broadcast('announce', { t: t }); return true;
  }
  return false;
});
